def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c - 1] == 2 and grid[r][c + 1] == 2 and
                grid[r - 1][c] == 2 and grid[r + 1][c] == 2):
                centers.append((r, c))

    # Connect horizontally aligned diamonds, joining only the gap between
    # their outward-facing side points.
    by_row = {}
    for r, c in centers:
        by_row.setdefault(r, []).append(c)
    for r, cols in by_row.items():
        cols.sort()
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1

    # Connect vertically aligned diamonds in the same way.
    by_col = {}
    for r, c in centers:
        by_col.setdefault(c, []).append(r)
    for c, rows in by_col.items():
        rows.sort()
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1

    return out
